                now_ms: () => (activeCallbacks ? activeCallbacks.nowMs() : 0),
                poll_status: (nodes, depth, score, bestCode, forceProgress) => (activeCallbacks ? activeCallbacks.pollStatus(nodes, depth, score, bestCode, forceProgress) : 0),
                tt_probe: (kl, kh, b0, b1, b2, w0, w1, w2, ac, rem, ql, ts) => (activeCallbacks && cachedTtIo)
